# durations.py
import re

def parse_duration(text):
    total = 0
    for value, unit in re.findall(r"(\d+)([hms])", text):
        value = int(value)
        if unit == "h":
            total += value * 3600
        elif unit == "m":
            total += value * 60
        else:
            total += value
    return total
